function isOverLimit(amount, limit) {
  return amount > limit;
}

// the only test
test('flags amounts over the limit', () => {
  expect(isOverLimit(150, 100)).toBe(true);   // clearly over
  expect(isOverLimit(50, 100)).toBe(false);   // clearly under
});

// MUTANT: return amount >= limit;

