tasks.setup:
const original = (amount, limit) => amount > limit;
const mutant = (amount, limit) => amount >= limit;

// the weak suite: only 'clearly over' / 'clearly under', never the boundary
function suite(fn) {
  const ok =
    fn(150, 100) === true &&
    fn(50, 100) === false;
  return ok; // true = suite passes (green)
}

const passesOriginal = suite(original);
const passesMutant = suite(mutant);

// a mutant is KILLED when the suite passes on the original but FAILS on the mutant
if (passesOriginal && !passesMutant) {
  console.log('mutant killed');
} else if (passesOriginal && passesMutant) {
  console.log('mutant survived');
} else {
  console.log('suite broken on original');
}
